package com.eventos.api.service;
import com.eventos.api.dto.EventDtos.*; import com.eventos.api.entity.*; import com.eventos.api.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*; import java.util.stream.*;
@Service public class EventService { private final EventRepository events; private final AdminRepository admins; public EventService(EventRepository events,AdminRepository admins){this.events=events;this.admins=admins;} private View view(Event e){return new View(e.getId(),e.getName(),e.getDate(),e.getLocation(),e.getImageUrl());} public List<View> list(Long adminId){return events.findAllByAdminIdOrderByDateAsc(adminId).stream().map(this::view).collect(Collectors.toList());} public View create(Long adminId,Create b){Admin a=admins.findById(adminId).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));Event e=new Event();e.setName(b.name);e.setDate(b.date);e.setLocation(b.location);e.setImageUrl(b.imageUrl);e.setAdmin(a);return view(events.save(e));} public View update(Long adminId,Long id,Update b){Event e=owned(id,adminId);e.setDate(b.date);e.setLocation(b.location);return view(events.save(e));} public void delete(Long adminId,Long id){events.delete(owned(id,adminId));} private Event owned(Long id,Long adminId){return events.findByIdAndAdminId(id,adminId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento não encontrado."));} }
